import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.time.LocalDate;

interface OrderRepository extends PagingAndSortingRepository<OrderEntity, Long> {

    @Query("select oi.product.id, sum(oi.quantity) as totalQty "
         + "from OrderItemEntity oi group by oi.product.id order by totalQty desc")
    Page<Object[]> topSellingProducts(Pageable pageable);

    Page<OrderEntity> findByCreatedAtBetween(
        @Param("from") LocalDate from, @Param("to") LocalDate to, Pageable pageable);

    Page<OrderEntity> findByUserId(@Param("userId") Long userId, Pageable pageable);
}

